// FUNCTION: BFME2 0x00201B05 size=76 name=?populateGameFonts@HeaderTemplateManager@@QAEXXZ evidence=N:ledger
void HeaderTemplateManager::populateGameFonts()
{
    for (HeaderTemplateList::iterator it = m_headerTemplateList.begin(); it != m_headerTemplateList.end(); ++it) {
        HeaderTemplate *headerTemplate = *it;
        Real pointSize = TheGlobalLanguageData->adjustFontSize(headerTemplate->m_point);
        headerTemplate->m_font = TheFontLibrary->getFont(&headerTemplate->m_fontName, pointSize, headerTemplate->m_bold);
    }
}

