// FUNCTION: BFME2 0x00201CAF size=133 name=?parseHeaderTemplateDefinition@INI@@SAXPAV1@@Z evidence=N:ledger

void INI::parseHeaderTemplateDefinition(INI *ini)
{
	AsciiString name;
	name.set(ini->getNextToken());
	HeaderTemplate *header = TheHeaderTemplateManager->findHeaderTemplate(name);
	if (!header)
		header = TheHeaderTemplateManager->newHeaderTemplate(name);
	ini->initFromINI(header, HeaderTemplate::m_headerFieldParseTable);
}


